const APP: &str = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>DOCX Editor</Application><DocSecurity>0</DocSecurity></Properties>"#;

fn core_properties(now: &str) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title></dc:title><dc:creator></dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">{now}</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">{now}</dcterms:modified></cp:coreProperties>"#
    )
}

/// The parts of a blank document, in conventional order.
pub fn blank_package() -> Package {
    let now = utc_timestamp(SystemTime::now());
    let parts = vec![
        Part::new("[Content_Types].xml", CONTENT_TYPES.as_bytes().to_vec()),
        Part::new("_rels/.rels", PACKAGE_RELS.as_bytes().to_vec()),
        Part::new("word/document.xml", DOCUMENT.as_bytes().to_vec()),
        Part::new("word/_rels/document.xml.rels", DOCUMENT_RELS.as_bytes().to_vec()),
        Part::new("word/styles.xml", BLANK_STYLES.as_bytes().to_vec()),
        Part::new("word/settings.xml", SETTINGS.as_bytes().to_vec()),
        Part::new("docProps/core.xml", core_properties(&now).into_bytes()),
        Part::new("docProps/app.xml", APP.as_bytes().to_vec()),
    ];
    Package::from_parts(parts)
}

/// Formats a time as `YYYY-MM-DDTHH:MM:SSZ`.
fn utc_timestamp(time: SystemTime) -> String {
    let secs = time.duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    let (days, rem) = (secs / 86_400, secs % 86_400);
    let (year, month, day) = civil_from_days(days as i64);
    format!("{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}Z", rem / 3600, rem % 3600 / 60, rem % 60)
}

/// Converts days since 1970-01-01 to a calendar date (Howard Hinnant's
/// algorithm).
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let month = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let year = yoe + era * 400 + i64::from(month <= 2);
    (year, month, day)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn timestamps() {
        assert_eq!(utc_timestamp(UNIX_EPOCH), "1970-01-01T00:00:00Z");
        assert_eq!(utc_timestamp(UNIX_EPOCH + Duration::from_secs(951_782_400)), "2000-02-29T00:00:00Z");
        assert_eq!(utc_timestamp(UNIX_EPOCH + Duration::from_secs(1_795_035_968)), "2026-11-18T21:06:08Z");
    }

    #[test]
    fn every_part_is_well_formed_xml() {
        for part in blank_package().parts() {
            crate::xml::XmlDocument::parse(&part.data).unwrap_or_else(|e| panic!("{}: {e}", part.name));
        }
    }
}
